def min_Jumps(steps, d):
    (a, b) = steps
    temp = a
    a = min(a, b)
    b = max(temp, b)
    if d == 0:
        return 0
    if d == a or d == b:
        return 1
    if d < a + b:
        return 2
    return (d + b - 1) / b

